def find_chapter_files():
    result = {}
    for fname in os.listdir(BASE):
        if not fname.lower().startswith("politychapter"):
            continue
        if not fname.lower().endswith((".html", ".txt")):
            continue
        m = re.search(r"politychapter([\d,\s]+)", fname, re.IGNORECASE)
        if not m:
            continue
        nums_str = m.group(1).strip().rstrip(",")
        nums = [int(x.strip()) for x in nums_str.split(",") if x.strip().isdigit()]
        for n in nums:
            result[n] = fname
    return result

def extract_all_pages(html_content):
    pages = []
    search_pos = 0
    while True:
        m = re.search(r'<div\s+class="page"[^>]*>', html_content[search_pos:])
        if not m:
            break
        start = search_pos + m.end()
        depth = 1
        i = start
        while i < len(html_content) and depth > 0:
            next_open = html_content.find("<div", i)
            next_close = html_content.find("</div>", i)
            if next_close == -1:
                break
            if next_open != -1 and next_open < next_close:
                depth += 1
                i = next_open + 4
            else:
                depth -= 1
                i = next_close + 6
        pages.append(html_content[start:i-6])
        search_pos = i
    return pages

def clean_page(page_html):
    page_html = re.sub(r'<div\s+class="page-footer">.*?</div>', '', page_html, flags=re.DOTALL)
    page_html = re.sub(r'<script.*?</script>', '', page_html, flags=re.DOTALL)
    page_html = re.sub(r'<span>[^<]*Page\s*\d+[^<]*</span>', '', page_html, flags=re.IGNORECASE)
    page_html = re.sub(r'\n\s*\n', '\n', page_html).strip()
    return page_html

def build_notes():
    file_map = find_chapter_files()
    print("Found chapter files:")
    for n in sorted(file_map.keys()):
        print(f"  Ch{n:>2}  <-  {file_map[n]}")
    print()

    entries = []
    for n in range(1, 19):
        if n not in file_map:
            print(f"[skip] Ch{n}: no file found")
            continue

        path = os.path.join(BASE, file_map[n])
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            html = f.read()

        all_pages = extract_all_pages(html)
        if not all_pages:
            print(f"[warn] Ch{n}: no page div found")
            continue

        chosen_pages = []
        for pg in all_pages:
            if re.search(rf'\b{n}\.\d', pg) or re.search(rf'Chapter\s+{n}\b', pg, re.IGNORECASE):
                chosen_pages.append(pg)

        if not chosen_pages:
            nums_in_file = []
            m = re.search(r"politychapter([\d,\s]+)", file_map[n], re.IGNORECASE)
            if m:
                nums_in_file = [int(x.strip()) for x in m.group(1).split(",") if x.strip().isdigit()]
            if nums_in_file:
                base = min(nums_in_file)
                idx = n - base
                if 0 <= idx < len(all_pages):
                    chosen_pages = [all_pages[idx]]

        if not chosen_pages:
            chosen_pages = all_pages

        merged_body = "\n".join(clean_page(p) for p in chosen_pages)
        meta = CHAPTER_META.get(n, {"title": f"Polity Chapter {n}", "icon": "📘", "read": "15 min", "tags": ["Polity"]})

        entry = {
            "id": f"polity-ch{n}",
            "subject": "Polity",
            "chapterNo": n,
            "title": meta["title"],
            "date": "2026-09-16",
            "readTime": meta["read"],
            "icon": meta["icon"],
            "tags": meta["tags"],
            "summary": f"Complete exam-ready guide to {meta['title']}.",
            "body": merged_body
        }
        entries.append(entry)
        print(f"[ok] Ch{n}: {len(merged_body):,} chars ({len(chosen_pages)} page(s))")

    entries.sort(key=lambda e: e["chapterNo"])

    js = "/* NOTES.JS — auto-generated */\n\n"
    js += "const NOTES = " + json.dumps(entries, ensure_ascii=False, indent=2) + ";\n"

    out = os.path.join(BASE, "notes.js")
    with open(out, "w", encoding="utf-8") as f:
        f.write(js)
    print(f"\nOK Wrote {out} ({len(entries)} chapters)\n")


