def build_quizzes():
    obj = {}
    for key, data in QUIZ_DATA.items():
        questions = []
        for q, opts, ans, expl in data["questions"]:
            questions.append({"q": q, "options": opts, "answer": ans, "explain": expl})
        obj[key] = {
            "title": data["title"],
            "subject": "Polity",
            "icon": data["icon"],
            "chapterNo": data.get("chapterNo", 0),
            "level": data.get("level", ""),
            "questions": questions
        }

    js = "/* QUIZZES.JS — auto-generated by build.py */\n\n"
    js += "const QUIZ_BANK = " + json.dumps(obj, ensure_ascii=False, indent=2) + ";\n"

    out = os.path.join(BASE, "quizzes.js")
    with open(out, "w", encoding="utf-8") as f:
        f.write(js)
    total = sum(len(v["questions"]) for v in obj.values())
    print(f"OK Wrote {out} ({len(obj)} topics, {total} questions)\n")


def build_chapter_quiz_links():
    obj = {}
    for n, topic_keys in CHAPTER_TO_QUIZ_TOPIC.items():
        if isinstance(topic_keys, list):
            obj[f"polity-ch{n}"] = topic_keys
        elif topic_keys in QUIZ_DATA:
            obj[f"polity-ch{n}"] = [topic_keys]

    js = "/* CHAPTER_QUIZZES.JS — auto-generated by build.py */\n\n"
    js += "const CHAPTER_QUIZ_TOPICS = " + json.dumps(obj, ensure_ascii=False, indent=2) + ";\n"

    out = os.path.join(BASE, "chapter_quizzes.js")
    with open(out, "w", encoding="utf-8") as f:
        f.write(js)
    print(f"OK Wrote {out} ({len(obj)} chapter->quiz links)\n")


if __name__ == "__main__":
    print("=" * 60)
    print("  Building notes.js, quizzes.js, chapter_quizzes.js")
    print("=" * 60)
    build_notes()
    build_quizzes()
    build_chapter_quiz_links()
    print("=" * 60)
    print("  DONE")
    print("=" * 60)